import { context, createContextKey } from "@opentelemetry/api";
const CONVERSATION_ID_ATTRIBUTE = "cursor.conversation.id";
const conversationIdKey = createContextKey(CONVERSATION_ID_ATTRIBUTE);
/** Bind the BDK session id onto a context. The value does not propagate. */
export function withConversationId(parent, sessionId) {
    return parent.setValue(conversationIdKey, sessionId);
}
function conversationIdFrom(ctx) {
    const value = ctx.getValue(conversationIdKey);
    return typeof value === "string" && value !== "" ? value : undefined;
}
/** Session id for the active turn, when this process set one. */
export function currentConversationId() {
    return conversationIdFrom(context.active());
}
/** Copy the session id onto a span that does not already set it. */
export function conversationIdSpanProcessor() {
    return {
        onStart(span, parentContext) {
            if (span.attributes[CONVERSATION_ID_ATTRIBUTE] !== undefined) {
                return;
            }
            const value = parentContext.getValue(conversationIdKey);
            if (typeof value !== "string" || value === "") {
                return;
            }
            span.setAttribute(CONVERSATION_ID_ATTRIBUTE, value);
        },
        onEnd() { },
        shutdown() {
            return Promise.resolve();
        },
        forceFlush() {
            return Promise.resolve();
        },
    };
}
